function jActivityIssues(d,step){const issues=[];const need=(v,msg)=>{if(!String(v??'').trim())issues.push(msg);};
 if(step===1){need(d.name,'Name the processing activity.');need(d.description,'Describe the activity and its business purpose.');if(!orgNode(d.orgScopeId)||orgNode(d.orgScopeId).kind!=='unit')issues.push('Choose its accountable branch / department / unit.');need(d.owner,'Assign an accountable owner.');if(d.owner===d.reviewer)issues.push('Use a different independent reviewer.');if(d.role==='Processor'){need(d.controllerName,'Identify the controller whose instructions you follow.');need(d.controllerContact,'Record the controller contact or directory reference.');}if(d.role==='Joint controller')need(d.jointArrangement,'Record the joint-controller arrangement.');}
 if(step===2){if(!d.subjects.length)issues.push('Choose the people whose information is used.');if(!d.dataCategories.length)issues.push('Choose at least one data category.');need(d.collection,'Describe the source of the information.');if(!d.purposes.length)issues.push('Add a purpose and its basis.');d.purposes.forEach((p,i)=>{need(p.purpose,`Purpose ${i+1}: describe the purpose.`);need(p.basis,`Purpose ${i+1}: select a basis or controller instruction.`);need(p.reference,`Purpose ${i+1}: add a supporting policy / instruction reference.`);});if(d.dataCategories.some(x=>['Biometric identifiers','Health information'].includes(x))&&!d.purposes.some(p=>p.condition.trim()))issues.push('Record the additional condition for sensitive-data processing for DPO review.');}
 if(step===3){if(!d.systems.length)issues.push('Add the system or repository holding the data.');d.systems.forEach((s,i)=>{need(s.name,`System ${i+1}: name the system.`);need(s.location,`System ${i+1}: record its storage location.`);});d.recipients.forEach((r,i)=>{need(r.name,`Recipient ${i+1}: identify the recipient.`);need(r.country,`Recipient ${i+1}: add destination country.`);need(r.data,`Recipient ${i+1}: describe data shared.`);need(r.purpose,`Recipient ${i+1}: state why it is shared.`);if(r.country!=='Nigeria')need(r.mechanism,`Recipient ${i+1}: record transfer safeguards or explicitly state pending review.`);});}
 if(step===4){d.retentions.forEach((r,i)=>{for(const [k,label] of [['dataset','data category'],['trigger','retention trigger'],['period','retention period'],['disposal','disposal method'],['reference','policy reference']])need(r[k],`Schedule ${i+1}: add the ${label}.`);});if(!d.retentions.length)issues.push('Add at least one retention schedule.');if(!d.controlIds.length)issues.push('Link at least one existing security control.');need(d.notice,'Link the privacy notice or instruction reference.');need(d.rightsRoute,'Record the rights-request route.');}
 if(step===5){for(const[k,label]of J_SCREEN)if(!['Yes','No','Unknown'].includes(d.screening[k]))issues.push(`Answer: ${label}.`);need(d.screeningContext,'Explain known risks, uncertainties and the assessment context.');need(d.nextReview,'Set the next review date.');if(d.nextReview&&d.nextReview<=S.asOf)issues.push('The next review date must be after the demo snapshot.');}
 return issues;}
