function jLossView(){const l=S.losses.find(l=>l.id===(current.params.get('id')||S.losses[0]?.id)),guard=jScopeDenied(l,'losses','losses');if(guard)return guard;return jCrumb([['Risk & losses','risks'],['Loss ledger','losses'],[l.id]])+jH(l.title,`${e(l.type)} · ${date(l.date)} · ${e(orgName(l.orgScopeId))}`,l.gross>recoveries(l)?btn('Record recovery','add-recovery',`data-id="${l.id}"`,'primary'):'','Loss event')+jFacts([['Gross booked loss',ngn(l.gross)],['Recoveries received',ngn(recoveries(l))],['Net loss',ngn(l.gross-recoveries(l))],['Event owner',e(l.owner)]])+jSection('Event facts','Scope follows the accountable unit of the linked risk.',jRead([['What happened',jText(l.note),true],['Linked risk',`<a href="#/risk?id=${l.risk}" class="j-inline-link">${e(S.risks.find(r=>r.id===l.risk)?.title||l.risk)}</a>`],['State',pill(l.status)]]))+panel('Recovery ledger','Dated entries remain separate from gross booked loss. Values are stored as integer kobo.',l.recoveries.length?table(['Received','Amount','Reference'],l.recoveries.map(r=>({cells:[date(r.date),ngn(r.amount),e(r.note)]}))):empty('No recovery entries','Record received recoveries with a date and reference. Potential recovery is not received money.'))+notice('Event date determines dashboard inclusion. The dashboard shows all recoveries received through the snapshot for those selected events. This event workspace shows its complete local ledger.','mini');}
function jControlView(){const c=S.controls.find(c=>c.id===(current.params.get('id')||S.controls[0]?.id)),guard=jScopeDenied(c,'controls','controls');if(guard)return guard;return jCrumb([['Risk & losses','risks'],['Controls','controls'],[c.id]])+jH(c.title,'One bank implementation, linked to the risks and requirements it addresses.','','Control implementation')+jFacts([['Owner',e(c.owner)],['Unit',e(c.unit)],['Effectiveness',pill(c.effectiveness)],['Linked risks',String(c.risks.length)]])+`<div class="j-two-col">${panel('Requirement mappings','Mapping alone does not prove satisfaction.',table(['Requirement','Objective'],c.reqs.map(id=>({cells:[e(findR(id)?.code||id),e(findR(id)?.title||'Unknown objective')]}))))}${panel('Risk relationships','Risk conclusions remain in their own reviewed records.',table(['Risk','Residual',''],c.risks.map(id=>{const r=S.risks.find(r=>r.id===id);return {cells:[e(r?.title||id),r?scoreBadge(r.residual):'Unknown',link('Open','risk?id='+id,'small')]};})))}</div><div class="mt16">${evidenceTable(S.evidence.filter(ev=>c.reqs.some(id=>findR(id)?.questions.includes(ev.question))&&scopeMatches(ev,'evidence')))}</div>`;}
function jEvidenceReview(){const x=S.evidence.find(x=>x.id===(current.params.get('id')||S.evidence[0]?.id)),guard=jScopeDenied(x,'evidence','evidence');if(guard)return guard;const can=x.status!=='Accepted';return jCrumb([['Documents','evidence'],[x.id]])+jH(x.name,'Review provenance, scope, freshness and acceptance as separate questions.','','Evidence review')+jFacts([['Target',e(targetName(x.target))],['Contributor',e(x.owner)],['Freshness',pill(evQuality(x))],['Review state',pill(x.status)]])+`<div class="j-review-grid"><div>${jSection('Assessment context','',jRead([['Program',jText(S.programs.find(p=>p.id===x.program)?.name)],['Question',jText(findQ(x.question)?.title||x.question)],['Observed',date(x.observed)],['Valid through',date(x.expires)],['Evidence ID',e(x.id)]]))+`<div class="j-evidence-placeholder">${icon('file')}<strong>Document content is not available in this demo</strong><p>This is a metadata-only record. Production review must provide the authorised artifact, provenance and relevant assessment context here.</p></div>`}</div><div>${can?`<form data-j-submit="evidence-decision" data-id="${x.id}">${jSection('Acceptance decision','A reviewer cannot accept their own evidence or treat expired evidence as current.',`<div class="j-fields">${select('reviewer','Acting reviewer · demo',J_PEOPLE,'Ifeoma Nwosu')}${select('decision','Decision',['Accept','Request changes'],'Request changes')}${area('note','Review rationale','','required minlength="10"')}</div><div class="j-error" role="alert"></div><button class="btn primary mt16" type="submit">Record document review</button>`)}</form>`:jSection('Accepted document review','The historical decision remains visible.',jRead([['Reviewer',jText(x.review?.by)],['Date',date(x.review?.date)],['Rationale',jText(x.review?.note),true]]))}</div></div>`;}
function jRequirementReview(){const p=S.programs.find(p=>p.id===(current.params.get('id')||S.programs[0]?.id)),guard=jScopeDenied(p,'programs','programs');if(guard)return guard;const rid=current.params.get('requirement')||p.reqs[0],r=findR(rid);if(!r||!p.reqs.includes(rid))return jH('Requirement not in this program','Return to the program requirement list.',link('Open program','program?id='+p.id,'primary'));const t=selectedTarget(p),a=getAssessment(p,t),ev=evaluation(p,t,rid),can=!p.excluded[rid]&&a.status==='Submitted'&&!a.reviewedReqs?.includes(rid),back=`program?id=${p.id}&target=${encodeURIComponent(t)}&tab=requirements`;
 return jCrumb([['Programs','programs'],[p.name,back],[r.code]])+jH(r.title,`${e(r.code)} · ${e(targetName(t))}`,link('Back to requirements',back,'quiet'),'Requirement evaluation')+jFacts([['Current conclusion',pill(ev.status)],['Assessment state',pill(a.status)],['Submitted by',jText(a.submittedBy)],['Source version','v'+r.version]])+`<div class="j-review-grid"><div><article class="j-review-doc"><h3>Source obligation</h3><p>${e(r.source)}</p>${p.overrides[rid]?`<hr class="divider"><h3>Program tailoring</h3><p>${e(p.overrides[rid])}</p>`:''}</article>${r.questions.map(qid=>{const q=findQ(qid),items=S.evidence.filter(z=>z.program===p.id&&z.target===t&&z.question===qid);return jSection(q.id+' · '+e(q.title),'Answer and evidence for this exact target.',`<div class="source-block"><strong>Response</strong><p class="small mb0">${e(a.answers[qid]||'Not submitted')}</p></div>${items.map(z=>`<div class="list-row"><div class="grow"><strong>${e(z.name)}</strong><small>${date(z.observed)} · ${pill(evQuality(z))} ${pill(z.status)}</small></div>${link('Review evidence','evidence-review?id='+z.id,'small')}</div>`).join('')||'<p class="small muted mt16">No scoped evidence linked.</p>'}`);}).join('')}</div><div>${can?`<form data-j-submit="requirement-decision" data-id="${rid}">${jSection('Record the scoped conclusion','Evidence acceptance does not automatically satisfy this requirement.',`<div class="j-fields">${select('reviewer','Acting reviewer',J_PEOPLE,p.reviewer)}${select('decision','Requirement conclusion',['Satisfied','Partially satisfied','Not satisfied'],'Partially satisfied')}${area('note','Evaluation rationale','','required minlength="10"')}</div><div class="j-error" role="alert"></div><button class="btn primary mt16" type="submit">Record conclusion</button>`)}</form>`:jSection('Decision readiness','',notice(p.excluded[rid]?'The requirement is not applicable in this program.':a.reviewedReqs?.includes(rid)?'This submitted run already has a recorded conclusion.':'Submit the assessment before recording a conclusion.','mini')+(ev.note?`<p class="small mt16">${e(ev.note)}</p>`:''))}</div></div>`;}
function jSetPath(obj,path,value){const parts=path.split('.');requireValue(!parts.some(p=>['__proto__','prototype','constructor'].includes(p)),'Invalid field path.');let at=obj;for(const k of parts.slice(0,-1)){requireValue(at[k]!==undefined,'Field is no longer present.');at=at[k];}at[parts.at(-1)]=value;}
function jGetPath(obj,path){return path.split('.').reduce((v,k)=>v?.[k],obj);}
function jShowError(message,root=document){const box=$('#j-error',root)||$('.j-error',root);if(box){box.textContent=message;box.focus?.();box.scrollIntoView({block:'center'});}else toast(message);}
function jSafe(fn){return el=>{try{fn(el);}catch(err){jShowError(err.message);}};}
function jWizardSize(d){return d.kind==='activity'?6:d.kind==='dpia'?5:d.kind==='case'?3:J_OPERATION_STEPS[d.kind].length;}
function jWizardIssues(d,step){return d.kind==='activity'?jActivityIssues(d.data,step):d.kind==='dpia'?jDpiaIssues(d.data,step):d.kind==='case'?jCaseIssues(d.data,step):jOperationIssues(d,step);}
function jWizardGo(step){const d=jDraft();requireValue(d,'The draft is no longer available.');const count=jWizardSize(d),now=jSteps(count);requireValue(step>=1&&step<=count,'Invalid workflow step.');if(step>now){const issues=jWizardIssues(d,now);requireValue(!issues.length,issues.join(' '));}d.step=step;save();go(current.name+'?draft='+d.id+'&step='+step);}
function jSaveExit(){const d=jDraft();save();const destination=d.kind==='activity'?'privacy?tab=register':d.kind==='dpia'?'dpia?id='+d.recordId:d.kind==='case'?'privacy?tab=cases':d.kind==='vendor'?'vendors':d.kind==='cycle'?'rcsa':d.kind==='loss'?'losses':'risks';go(d.kind==='dpia'&&!d.recordId?'privacy?tab=dpias':destination);toast('Working draft saved. Published records and live ratings are unchanged.');}
function jSubmitCase(){const d=jDraft(),issues=[...jCaseIssues(d.data,1),...jCaseIssues(d.data,2)];requireValue(!issues.length,issues.join(' '));const a=jRecord(d.data.activity);requireValue(!d.data.activity||a,'Processing activity not found.');const x={...clone(d.data),id:uid(d.data.type==='Rights request'?'REQ':'INC'),orgScopeId:a?.orgScopeId||d.data.orgScopeId,state:'Triage',history:[]};jLog(x,'Case opened','Initial facts and target basis recorded. No external message sent.',x.owner);S.privacyCases.unshift(x);delete S.journeyDrafts[d.id];audit('Opened '+x.type,x.activity,x.owner);go('privacy-case?id='+x.id);}
const J_NEW_ROWS={purposes:()=>({id:uid('P'),purpose:'',basis:'',reference:'',condition:''}),systems:()=>({id:uid('SYS'),name:'',location:'Nigeria',role:'System of record'}),recipients:()=>({id:uid('RECIP'),name:'',engagement:'',role:'Processor',country:'Nigeria',data:'',purpose:'',agreement:'',mechanism:'',review:'Needs review'}),retentions:()=>({id:uid('RET'),dataset:'',trigger:'',period:'',disposal:'',reference:''}),risks:jDefaultRisk};
