window.CS_JOURNEY_GROUPS=Object.fromEntries(Object.keys(J_ROUTES).map(r=>[r,['risk','loss','control','setup'].includes(r)?'risks':['evidence-review','requirement-review'].includes(r)?'programs':'privacy']));
Object.assign(titles,{activity:'Processing activity','activity-wizard':'Register processing activity','activity-version':'Published activity revision',dpia:'Privacy impact assessment','dpia-wizard':'Prepare DPIA','privacy-case':'Privacy case','case-intake':'Log privacy case',setup:'Guided setup',risk:'Risk record',loss:'Loss event',control:'Control implementation','evidence-review':'Evidence review','requirement-review':'Requirement evaluation'});
privacyView=jPrivacyView;
// Keep list filters and scroll when returning from a task. Keys include the scope.
const J_VIEW_MEMORY=new Map();let jPreviousKey='';const jPriorRender=render;
render=function(){journeyInit();if(jPreviousKey&&$('#main-content'))J_VIEW_MEMORY.set(jPreviousKey,{filters:clone(filters),y:scrollY});jPriorRender();const r=route();jPreviousKey=r.name+'?'+r.params.toString()+'|'+selectedScope();const remembered=J_VIEW_MEMORY.get(jPreviousKey);if(remembered){filters={...remembered.filters};if($('[data-filter]'))$('[data-filter]').value=filters.search;if($('[data-unit-filter]'))$('[data-unit-filter]').value=filters.unit;filteredRows();if(!['activity-wizard','dpia-wizard','setup','case-intake'].includes(r.name))requestAnimationFrame(()=>scrollTo(0,remembered.y));}
 if(r.name==='setup'&&jDraft()?.kind==='vendor'){$$('.nav-link.active').forEach(n=>n.classList.remove('active'));$('.nav-link[href="#/vendors"]')?.classList.add('active');}
 const d=jDraft();if(['dpia-wizard','case-intake','setup'].includes(r.name)&&d){const note=document.createElement('p');note.className='j-pinned';note.textContent='Draft target is pinned. Changing the navigation scope does not reassign or discard this work.';$('.j-wizard-body')?.prepend(note);}
 // Saved drafts are resumable from each owning workspace, not hidden in a modal.
 const kinds={vendors:['vendor'],risks:['risk'],losses:['loss'],rcsa:['cycle']};let ds=[];
 if(kinds[r.name])ds=Object.values(S.journeyDrafts).filter(d=>kinds[r.name].includes(d.kind));
 if(r.name==='privacy'&&['dpias','cases'].includes(r.params.get('tab')))ds=Object.values(S.journeyDrafts).filter(d=>d.kind===(r.params.get('tab')==='dpias'?'dpia':'case'));
 ds=ds.filter(d=>!selectedScope()||scopeMatches(d.data,'drafts'));
 if(ds.length){const section=`<section class="j-section mt16"><h2>Saved working drafts</h2><p class="j-description">Unsubmitted work is kept separate from active records.</p>${ds.map(d=>`<div class="list-row"><div class="grow"><strong>${e(d.data.name||d.data.title||d.data.service||'Untitled '+d.kind)}</strong><small>Step ${d.step||1} · local working copy</small></div>${link('Resume',`${d.kind==='dpia'?'dpia-wizard':d.kind==='case'?'case-intake':'setup'}?draft=${d.id}&step=${d.step||1}`,'small')}${btn('Discard','j-discard-draft',`data-id="${d.id}"`,'quiet small')}</div>`).join('')}</section>`;$('.page-footer')?.insertAdjacentHTML('beforebegin',section);}
 if(['activity-wizard','dpia-wizard','setup','case-intake'].includes(r.name)){const active=$('.j-stage .active');if(active&&innerWidth<700)active.scrollIntoView({inline:'center',block:'nearest'});}
};
window.CLEAR_SIGHT_JOURNEYS=Object.freeze({version:'2.4-demo',getDrafts:()=>clone(S.journeyDrafts),getPrivacy:()=>clone({records:S.processing,dpias:S.dpias,cases:S.privacyCases}),activityIssues:(id)=>jAllIssues(jData(jRecord(id))),getViews:()=>Object.keys(J_ROUTES)});
